using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.Settings;
namespace TechnifyERP.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class SettingsController(IAcademySettingsService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAsync(ct));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Save(string academyName,string shortName,string? website,string academicYear,string? email,string? phone,string? address,CancellationToken ct){var r=await service.SaveAsync(new(academyName,shortName,website,academicYear,email,phone,address),ct);TempData[r==SettingsActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==SettingsActionResult.Success?"Academy settings save ho gayi.":"Required fields complete karein.";return RedirectToAction(nameof(Index));}}
